def run_command(
    cmd,
    stdout=None,
    stderr=None,
    shell=False,
    timeout=None,
    cwd=None,
    env=None,
    universal_newlines=False,
):
  if stdout is None:
    stdout = subprocess.PIPE
  if stderr is None:
    stderr = subprocess.PIPE
  process = subprocess.Popen(
      cmd,
      stdout=stdout,
      stderr=stderr,
      shell=shell,
      cwd=cwd,
      env=env,
      universal_newlines=universal_newlines,
  )
  timer = None
  timer_triggered = threading.Event()
  if timeout and timeout > 0:

    def timeout_expired():
      timer_triggered.set()
      process.terminate()

    timer = threading.Timer(timeout, timeout_expired)
    timer.start()
  out, err = process.communicate()
  if timer is not None:
    timer.cancel()
  if timer_triggered.is_set():
    raise subprocess.TimeoutExpired(
        cmd=cmd, timeout=timeout, output=out, stderr=err
    )
  logging.debug(
      'cmd: %s, stdout: %s, stderr: %s, ret: %s',
      cli_cmd_to_string(cmd),
      out,
      err,
      process.returncode,
  )
  return process.returncode, out, err


def start_standing_subprocess(
    cmd,
    shell=False,
    env=None,
    stdout=subprocess.PIPE,
    stderr=subprocess.PIPE,
):
  logging.debug('Starting standing subprocess with: %s', cmd)
  proc = subprocess.Popen(
      cmd,
      stdin=subprocess.PIPE,
      stdout=stdout,
      stderr=stderr,
      shell=shell,
      env=env,
  )
  proc.stdin.close()
  proc.stdin = None
  logging.debug('Started standing subprocess %d', proc.pid)
  return proc


